-- Apply after 019. Preserve RLS while filtering full, inline record panels.
begin;
do $$begin if not exists(select 1 from public.jf_schema_versions where version='019_import_notifications') then raise exception 'Apply migration 019 first.';end if;end$$;
create index jf_orders_customer_profile on public.jf_orders(shop_id,customer_id,created_at desc) where archived_at is null;
create index jf_orders_phone_history on public.jf_orders(shop_id,recipient_phone);
create or replace function public.jf_workspace_page(target_shop uuid,entity text,filters jsonb default '{}',page_number integer default 0) returns jsonb
language plpgsql stable security invoker set search_path='' as $$
declare result jsonb;st text:=coalesce(filters->>'status','all');search text:=trim(coalesce(filters->>'search',''));agent_id uuid:=nullif(filters->>'agent_id','')::uuid;
begin
 if page_number is null or page_number<0 or length(search)>200 then raise exception 'Invalid page filter.';end if;
 if entity='customers' then
  with c as(select c.*,f.status followup_status,f.call_outcome,f.callback_at from public.jf_customers c left join public.jf_followups f on f.shop_id=c.shop_id and f.customer_id=c.id where c.shop_id=target_shop and c.archived_at is null and (agent_id is null or c.assigned_membership_id=agent_id)
   and (coalesce(filters->>'source','')='' or lower(c.source)=lower(filters->>'source')) and (coalesce(filters->>'tag','')='' or c.unassignment_tag=filters->>'tag') and (coalesce(filters->>'response','')='' or f.call_outcome=lower(filters->>'response')) and (coalesce(filters->>'call','')='' or lower(replace(filters->>'call',' ','_'))='connected' and f.call_outcome in('connected','positive','negative','intermediate') or lower(replace(filters->>'call',' ','_'))='not_connected' and f.call_outcome in('not_connected','no_answer','busy')) and (search='' or c.full_name ilike '%'||search||'%' or c.phone ilike '%'||search||'%')
   and (st='confirmed' and exists(select 1 from public.jf_orders x where x.shop_id=target_shop and x.customer_id=c.id and x.archived_at is null and x.status not in('draft','cancelled')) or st='attempted' and f.call_outcome is not null and f.call_outcome<>'not_attempted' or st='failed' and f.call_outcome is not null and f.call_outcome<>'not_attempted' and not exists(select 1 from public.jf_orders x where x.shop_id=target_shop and x.customer_id=c.id and x.archived_at is null and x.status not in('draft','cancelled')) or lower(replace(c.workflow_label,' ','_'))=st or st in('no_answer','busy') and f.call_outcome=st or st='all' or st='unassigned' and c.assigned_membership_id is null or st='assigned' and c.assigned_membership_id is not null or st='permanent' and c.permanent or st='completed' and f.status='completed' or st='pending' and coalesce(f.status,'pending') in ('pending','callback') or st='cancelled' and f.status='cancelled' or st='connected' and f.call_outcome in ('connected','positive','negative','intermediate') or st='not_connected' and f.call_outcome in ('not_connected','no_answer','busy') or st='not_attempted' and (f.call_outcome is null or f.call_outcome='not_attempted') or st in ('positive','negative','intermediate') and f.call_outcome=st or st='callbacks' and f.status='callback' and f.callback_at<=now() or st='buyers' and f.status='completed' and exists(select 1 from public.jf_orders o where o.shop_id=target_shop and o.customer_id=c.id and o.archived_at is null and o.status not in ('draft','cancelled'))))
  select jsonb_build_object('total',(select count(*) from c),'rows',coalesce((select jsonb_agg(to_jsonb(p)||jsonb_build_object('latest_note',(select n.body from public.jf_notes n where n.shop_id=target_shop and n.customer_id=p.id order by n.created_at desc,n.id desc limit 1),'order_count',(select count(*) from public.jf_orders z where z.shop_id=target_shop and z.customer_id=p.id and z.archived_at is null))) from(select * from c order by updated_at desc,id limit 50 offset page_number::bigint*50) p),'[]')) into result;
 elsif entity='orders' then
  with o as(select o.* from public.jf_orders o where o.shop_id=target_shop and o.archived_at is null and (agent_id is null or o.assigned_membership_id=agent_id)
   and (nullif(filters->>'report_start','') is null or o.created_at>=(filters->>'report_start')::timestamptz) and (nullif(filters->>'report_end','') is null or o.created_at<(filters->>'report_end')::timestamptz) and (coalesce(filters->>'source','')='' or case when lower(o.source) in('website','facebook','whatsapp') then lower(o.source) else 'other' end=filters->>'source') and (nullif(filters->>'product_id','') is null or exists(select 1 from public.jf_order_items i where i.shop_id=target_shop and i.order_id=o.id and i.product_id=(filters->>'product_id')::uuid)) and (coalesce(filters->>'tag','')='' or exists(select 1 from public.jf_customers c where c.shop_id=target_shop and c.id=o.customer_id and c.unassignment_tag=filters->>'tag')) and (coalesce(filters->>'response','')='' or exists(select 1 from public.jf_followups f where f.shop_id=target_shop and f.customer_id=o.customer_id and f.call_outcome=lower(filters->>'response'))) and (coalesce(filters->>'call','')='' or exists(select 1 from public.jf_followups f where f.shop_id=target_shop and f.customer_id=o.customer_id and (lower(replace(filters->>'call',' ','_'))='connected' and f.call_outcome in('connected','positive','negative','intermediate') or lower(replace(filters->>'call',' ','_'))='not_connected' and f.call_outcome in('not_connected','no_answer','busy')))) and (search='' or o.order_number ilike '%'||search||'%' or o.recipient_name ilike '%'||search||'%' or o.recipient_phone ilike '%'||search||'%')
   and(st='all' or st='confirmed' and o.status not in ('draft','cancelled') or st='ready_to_book' and o.status in ('confirmed','ready_to_book') or st not in ('confirmed','ready_to_book') and o.status=st))
  select jsonb_build_object('total',(select count(*) from o),'rows',coalesce((select jsonb_agg(to_jsonb(p)) from(select * from o order by created_at desc,id limit 50 offset page_number::bigint*50) p),'[]')) into result;
 else raise exception 'Choose customers or orders.';end if;
 return result;
end $$;

insert into public.jf_schema_versions(version) values('020_direct_record_panels');commit;
